pub struct CurveData<'a>(pub &'a Object);

impl<'a> TypedView<'a> for CurveData<'a> {
    const CLASS: ClassId = classes::CurveData;
    #[inline]
    fn from_object(o: &'a Object) -> Self {
        CurveData(o)
    }
    #[inline]
    fn object(&self) -> &'a Object {
        self.0
    }
}

impl<'a> CurveData<'a> {
    /// The object's master resource identifier.
    #[inline]
    pub fn mrid(&self) -> &'a Mrid {
        self.0.mrid()
    }

    /// The point data values that define this curve.
    #[inline]
    pub fn curve(&self) -> Option<TypedRef<Curve<'static>>> {
        self.0
            .get(attrs::curve_data::Curve)
            .and_then(|v| v.as_reference())
            .map(|m| TypedRef::new(m.clone()))
    }

    /// Resolve `Curve` through `dataset`.
    #[inline]
    pub fn curve_in<'d>(&self, dataset: &'d Dataset) -> Option<Curve<'d>> {
        let m = self.0.get(attrs::curve_data::Curve)?.as_reference()?;
        dataset.by_mrid(m).map(Curve)
    }

    /// The data value of the X-axis variable,  depending on the X-axis units.
    ///
    /// Unit: `none`.
    #[inline]
    pub fn xvalue(&self) -> Option<f64> {
        self.0
            .get(attrs::curve_data::xvalue)
            .and_then(|v| v.as_f64())
    }

    /// The data value of the  first Y-axis variable, depending on the Y-axis units.
    ///
    /// Unit: `none`.
    #[inline]
    pub fn y1value(&self) -> Option<f64> {
        self.0
            .get(attrs::curve_data::y1value)
            .and_then(|v| v.as_f64())
    }

    /// The data value of the second Y-axis variable (if present), depending on the Y-axis units.
    ///
    /// Unit: `none`.
    #[inline]
    pub fn y2value(&self) -> Option<f64> {
        self.0
            .get(attrs::curve_data::y2value)
            .and_then(|v| v.as_f64())
    }
}

